definition.raw:
The \textit{Kronecker series} $F_{\tau}: \C \times \C \rightarrow \C$~\cite{W,Z} is the meromorphic function defined by the formula
\begin{equation}
F_{\tau}(\xi,\alpha)=\frac{\theta_{\tau}'(0)\theta_{\tau}(\xi+\alpha)}{\theta_{\tau}(\xi)\theta_{\tau}(\alpha)}.
\end{equation}

Define a family $\{\omega^{(k)}\}_{k \geq 0}$ of real analytic differential one-forms on $E^{\times}_{\tau}$ by the formula
\begin{equation}
\Omega_{\tau}(\xi,\alpha)=\sum_{k \geq 0}\omega^{(k)}\alpha^{k-1}.
\end{equation}

(\cite{MMV}, Example 4.10)
We define the \textit{indefinite Eisenstein integral} by
\begin{equation} \label{eqn:inteis}
\calg_{2k}(\tau)=\int_{\tau}^{i\infty}G_{2k}(\tau')-2\zeta(2k)d\tau'+\int_0^{\tau}2\zeta(2k)d\tau'.
\end{equation}

\label{dfn:eMZV}
We define the A-elliptic multiple zeta value $I^A(n_1,\dots,n_r;\tau)$\footnote{In \cite{BMMS}, this is denoted by $\omega(n_1,...,n_r)$} to be the coefficient of $\ad^{n_1}(x)(y)\dots\ad^{n_r}(x)(y)$ in the regularized generating series
\begin{equation}
\lim_{t \to 0}(-2\pi it)^{\ad(x)(y)}\exp\bigg[\int_{\alpha_t^{1-t}}\ad(x)\Omega_{\tau}(\xi,\ad(x)(y))\bigg](-2\pi it)^{-\ad(x)(y)},
\end{equation}
where $\alpha_t^{1-t}$ denotes the restriction of the path $\alpha$ to the interval $[t,1-t]$, and for a differential one-form $\omega$, we write
\begin{equation}
\exp\bigg[\int \omega\bigg]=1+\sum_{k \geq 1}\int \underbrace{\omega\dots\omega}_{\textrm{k-times}}.
\end{equation}
The regularization of the integral is performed as in~\cite{Del}, Proposition 15.45 (with the order of integration reversed), with respect to the tangent vector $-\frac{\partial}{\partial z}=(-2\pi i)^{-1}\frac{\partial}{\partial \xi}$ at $0$ at the starting point of the path of integration (where $z=e^{2\pi i\xi}$), and with respect to the tangent vector $\frac{\partial}{\partial z}=(2\pi i)^{-1}\frac{\partial}{\partial \xi}$ at $0$ at the endpoint of the path of integration.

Recall that $A(\tau)$ is defined as
\begin{equation}
A(\tau)=X(z)^{-1}X(z+1),
\end{equation}
where $X(z)$ is the unique holomorphic function defined on $\{z \in \C \, | \, z=u+vi, \ u \mbox{ or } v \in (0,1)\} \subset \C$, which solves the equation 
\begin{equation}
\dd X(z)=-\ad(x)\Omega_{\tau}(\xi,\ad(x))(y) \cdot X(z),
\end{equation}
and satisfies $X(z) \sim (-2\pi iz)^{-\ad(x)(y)}$, as $z \to 0$, where we choose the principal branch of the logarithm so that $\log(\pm i)=\pm \frac{\pi i}{2}$.

Define the $\Q$-vector space of A-elliptic multiple zeta values to be
\begin{equation}
\eZ^A=\langle I^A(n_1,\dots,n_r;\tau) \, \vert \, n_1,\dots,n_r \geq 0 \rangle_{\Q} \subset \calo(\H).
\end{equation}
Also, we define its weight $N$ component to be
\begin{equation}
\eZ^A_N=\langle I^A(n_1,\dots,n_r;\tau) \, \vert \, n_1+\dots +n_r=N \rangle_{\Q} \subset \calo(\H).
\end{equation}

We denote by
\begin{equation}
\cL_l\eZ^A_N=\langle I^A(n_1,\dots,n_r;\tau) \in \eZ^A_N \, \vert \, r \leq l \rangle_{\Q}
\end{equation}
the $\Q$-subspace of A-elliptic multiple zeta values of weight $N$ and of length at most $l$. We also denote by
\begin{equation}
\gr^{\cL}_l\eZ^A_N
\end{equation}
the associated graded.

For $N \geq 0$, we define the length two \emph{Fay-shuffle space}, $\FSh_2(N)$ as the set of rational functions $P \in V'_N$, which satisfy
\begin{align} \label{eqn:fsh}
P(X,Y)+P(X+Y,-Y)+P(-X-Y,X)&=0, \quad P(X,Y)+P(Y,X)=0.
\end{align}

Let $n$ be a positive integer and consider the matrix $M_n=(m_{i,j})_{0 \leq i,j \leq n}$ with
\begin{equation}
m_{i,j}=\binom{2j+1}{i}-\delta_{2j+1,i},
\end{equation}
where $\delta$ denotes the Kronecker delta.

theorem.raw:
We have
\begin{equation} \label{eqn:l2}
D_{N,2}=\begin{cases}
0, & \mbox{if $N$ is even}\\
\left\lfloor \frac{N}{3} \right\rfloor+1, & \mbox{if $N$ is odd}.
\end{cases}
\end{equation}

\label{thm:BL}
Every homotopy invariant iterated integral on $E^{\times}_{\tau}$ is a $\C$-linear combination of coefficients of the words $x,y$ in the generating series
\begin{equation} \label{eqn:geniter}
T=1+\sum_{k \geq 1}\int \underbrace{J\dots J}_{\textrm{k-times}},
\end{equation}
where 
\begin{equation} \label{eqn:kzbeqn}
J=-\nu x+\ad(x)\Omega_{\tau}(\xi,\ad(x))(y)=-\nu x+\sum_{k \geq 0}\omega^{(k)}\ad^k(x)(y)
\end{equation} 
with $\nu=2\pi i \dd r$.

\label{thm:diff}
For all $r \geq 0$, we have
\begin{align} \label{eqn:diffenr}
2\pi i\frac{\partial}{\partial \tau}\cali^A(X_1,\dots,X_r;\tau)&=\wp_{\tau}^*(X_1)\cali^A(X_2,\dots,X_r;\tau)-\wp_{\tau}^*(X_r)\cali^A(X_1,\dots,X_{r-1};\tau) \notag\\
&+\sum_{i=1}^{r-1}(\wp_{\tau}^*(X_{i+1})-\wp_{\tau}^*(X_i))\cali^A(X_1,\dots,X_i+X_{i+1},\dots,X_r;\tau),
\end{align}
where $\wp_{\tau}^*(\alpha)=\sum_{k=-1}^{\infty}(2k+1)G_{2k+2}(\tau)\alpha^{2k}$ considered as a formal power series in $\alpha$.






\qed

\label{thm:weight}
Denote by
$
\bigoplus_{N \geq 0} \cL_2\eZ^A_N
$
the outer direct sum of the $\Q$-vector spaces $\cL_2\eZ^A_N$. The natural map
\begin{equation}
\bigoplus_{N \geq 0} \cL_2\eZ^A_N \rightarrow \calo(\H)
\end{equation}
induced by the inclusions $\cL_2\eZ^A_N \subset \calo(\H)$ is injective.

\label{mthm}
\begin{enumerate}
\item
Let $N \geq 0$ and $D_{N,2}:=\gr^{\cL}_2\eZ^A_N$. Then
\begin{equation}
D_{N,2}=\begin{cases}
0, & \mbox{if $N$ is even}\\
\left \lfloor \frac N3 \right \rfloor+1, & \mbox{if $N$ is odd}.
\end{cases}
\end{equation}
\item
Every $\Q$-linear relation between elliptic double zeta values is a consequence of Fay and shuffle relations.
\end{enumerate}

\label{thm:Fayshuf}
We have
\begin{equation}
\dim_{\Q}\FSh_2(N)=
\begin{cases}
0, & \mbox{if $N$ is even}\\
\left\lfloor \frac N3 \right\rfloor+1, & \mbox{if $N$ is odd.}
\end{cases}
\end{equation}

\label{thm:linind}
Let $N > 0$ be odd, and $k=\lfloor \frac N3 \rfloor$.
\begin{enumerate}
\item
The set
\begin{equation}
\calb_{N,2}=\left\{\frac{\partial}{\partial \tau} I^A(r,N-r;\tau) \; \vert \; 0 \leq r \leq k \right\}
\end{equation}
is linearly independent over $\Q$.
\item
We have 
\begin{equation}
\dim_{\Q}\cL_2\eZ^A_N \geq \left\lfloor \frac N3 \right\rfloor+1.
\end{equation}
\end{enumerate}

lemma.raw:
For every $n$, we have
\begin{equation} \label{eqn:LU}
M_n=L_n U_n.
\end{equation}

proposition.raw:
\label{prop:kro}
The one-form $\Omega_{\tau}(\xi,\alpha)$ satisfies the following properties:
\begin{enumerate}
\item
It is doubly periodic in $\xi$:
\begin{align}
\Omega_{\tau}(\xi+1,\alpha)=\Omega_{\tau}(\xi,\alpha), \quad \Omega_{\tau}(\xi+\tau,\alpha)=\Omega_{\tau}(\xi,\alpha).
\end{align}
Thus it descends to a formal differential one-form on $E^{\times}_{\tau}$.
\item
It is symmetric in its arguments, i.e.
\begin{equation}
\Omega_{\tau}(-\xi,-\alpha)=\Omega_{\tau}(\xi,\alpha).
\end{equation}





\item
It satisfies the Fay identity:
\begin{align}
\Omega_{\tau}(\xi_1,\alpha_1) \land \Omega_{\tau}(\xi_2,\alpha_2)&=\Omega_{\tau}(\xi_1-\xi_2,\alpha_1) \land \Omega_{\tau}(\xi,\alpha_1+\alpha_2) \notag \\
&+\Omega_{\tau}(\xi_2-\xi_1,\alpha_2) \land \Omega_{\tau}(\xi,\alpha_1+\alpha_2).
\end{align}
\item
We have the modular transformation formula
\begin{equation} \label{eqn:Omegamod}
\Omega_{\frac{a\tau+b}{c\tau+d}}((c\tau+d)^{-1}\xi,(c\tau+d)^{-1}\alpha)=(c\tau+d)\Omega_{\tau}(\xi,\alpha)
\end{equation}
for $\begin{pmatrix}a&b\\c&d\end{pmatrix} \in \SL_2(\Z)$.
\end{enumerate}

\label{prop:gradeis}
Let $\Eis_{2\pi i} \subset \calo(\H)$ be the $\Q$-vector subspace spanned by all products
\begin{equation}
(2\pi i)^j\calg_{2k}(\tau), \quad j,k \geq 0,
\end{equation}
and define a grading on $\Eis_{2\pi i}$ by giving $(2\pi i)^j\calg_{2k}(\tau)$ weight $j+2k$. Then $\Eis_{2\pi i}$ is a graded $\Q$-vector space.

\label{prop:compass}
For all $n_1,\dots,n_r \geq 0$, we have that $I^A(n_1,\dots,n_r;\tau)$ is equal to $(-1)^r$ times the coefficient of the word $\ad^{n_r}(x)(y)...\ad^{n_1}(x)(y)$ in the series
\begin{equation}
e^{-\pi i\ad(x)(y)}A(\tau),
\end{equation}
where $A(\tau)$ is Enriquez's A-associator (cf.~\cite{E2}, Section~5.2).

\label{prop:constterm}
Denote by $c_{n_1,\dots,n_r}$ the constant term in the Fourier expansion of $I^A(n_1,\dots,n_r;\tau)$. It is
\begin{equation}
c_n=
\begin{cases}
0 ,& \mbox{for $n=1$}\\
\frac{B_n}{n!}(2\pi i)^n, & \mbox{else},
\end{cases}
\end{equation}
and
\begin{equation}
c_{m,n}=
\begin{cases}
0, & \mbox{if $m=n=1$}\\
-\frac 12 (2\pi i)^{m+1}\frac{B_mB_1}{m!},  & \mbox{if $n=1$ and $m \neq 1$}\\
\frac 12 (2\pi i)^{m+n}\frac{B_mB_n}{m!n!} ,& \mbox{else},
\end{cases}
\end{equation}
where $B_n$ are the Bernoulli numbers defined by the series $\sum_{n \geq 0}\frac{B_n}{n!}t^n=\frac{t}{e^t-1}$.

\label{prop:Qrel}
For all $m,n \geq 0$, we have the following relations between elliptic double zeta values:
\begin{enumerate}
\item (Reflection relation)
\begin{equation}
I^A(m,n;\tau)=(-1)^{m+n}I^A(n,m;\tau)
\end{equation}
\item (Shuffle relation)
\begin{equation}
I^A(m,n;\tau)+I^A(n,m;\tau)=I^A(m)I^A(n)
\end{equation}




\item (Fay relation)
\begin{align}
I^A(m,n;\tau)&=-\delta_{m,1}\delta_{n,1}3\zeta(2)-(-1)^nI^A(0,m+n;\tau) \notag\\
&+\sum_{r=0}^n(-1)^{n-r}\binom{m-1+r}{m-1}I^A(m+r,n-r;\tau) \notag \\
&+\sum_{r=0}^m(-1)^{n+r}\binom{n-1+r}{n-1}I^A(n+r,m-r;\tau)
\end{align}
\end{enumerate}

$\eZ^A$ is a filtered $\Q$-algebra for the length filtration. More precisely, the multiplication law on $\eZ^A$ satisfies
\begin{equation}
\cL_l\eZ^A_N \cdot \cL_{l'}\eZ^A_{N'} \subset \cL_{l+l'}\eZ^A_{N+N'},
\end{equation}
for all $l,l',N,N' \geq 0$.

\label{prop:decomp}
For odd $N \geq 1$, we have
\begin{equation}
\FSh_2(N) \cong \FSh_2(N)^{pol} \oplus \Q \widetilde{P},
\end{equation}
where 
\begin{equation}
\widetilde{P}(X,Y)=\frac{X^{N-1}}{Y}-\frac{Y^{N-1}}{X}-\frac{X^{N-1}-Y^{N-1}}{X+Y},
\end{equation}
and $\FSh_2(N)^{pol}=\FSh_2(N) \cap V_{N-2}$ denotes the polynomial part of the Fay-shuffle space.

\label{prop:app}
We have
\begin{equation}
\det(M_n)=(2n+1)!!=1\cdot 3\cdot 5\dots\cdot(2n+1).
\end{equation}
In particular, $M_n$ is invertible for every $n$.

corollary.raw:
\label{cor:fk}
The form $\omega^{(k)}$ has modular weight $k+1$, i.e.
\begin{equation}
\omega^{(k)}_{\vert \gamma}=(c\tau+d)^{k+1}\omega^{(k)}
\end{equation}
where the action of $\gamma \in \SL_2(\Z)$ on $\omega^{(k)}$ is defined as in~\eqref{eqn:Omegamod}. Moreover, $\omega^{(k)}=f^{(k)}(\xi)\dd\xi$ is doubly periodic and antisymmetric/symmetric depending on the weight
\begin{equation}
f^{(k)}(-\xi)=(-1)^kf^{(k)}(\xi),
\end{equation}
and we have the Fay identity
\begin{align}
f^{(m)}(\xi_1)f^{(n)}(\xi_2)&=-(-1)^nf^{(m+n)}(\xi_1-\xi_2) \notag\\
&+\sum_{r=0}^{n}\binom{m+r-1}{m-1}f^{(n-r)}(\xi_2-\xi_1)f^{(m+r)}(\xi_1) \notag\\
&+\sum_{r=0}^{m}\binom{n+r-1}{n-1}f^{(m-r)}(\xi_1-\xi_2)f^{(n+r)}(\xi_2).
\end{align}
\qed

\label{cor:diff}


Elliptic multiple zeta values of length one are constant, i.e.
\begin{equation} \label{eqn:cor1}
2\pi i\frac{\partial}{\partial \tau}I^A(n;\tau)=0.
\end{equation}
More precisely, writing $I^A(n)$ instead of $I^A(n;\tau)$, we have $I^A(1)=0$ and
\begin{equation} \label{eqn:cor1b}
I^A(n)=\frac{(2\pi i)^nB_n}{n!}, \quad n \neq 1.
\end{equation}

In length two, we have
\begin{align} \label{eqn:cor2a}
2\pi i\frac{\partial}{\partial \tau}I^A(0,n;\tau)&=(-1)^n2\pi i\frac{\partial}{\partial \tau}I^A(n,0;\tau) \notag \\
&=-nG_{n+1}(\tau)I^A(0)+nG_0(\tau)I^A(n+1),
\end{align}
and if $m,n \neq 0$
\begin{align} \label{eqn:cor2b}
2\pi i\frac{\partial}{\partial \tau}I^A(m,n;\tau)&=-nG_{n+1}(\tau)I^A(m)+mG_{m+1}(\tau)I^A(n) \notag \\
&-(-1)^m(m+n)G_{m+n+1}(\tau)I^A(0) \notag \\
&+\sum_{k=1}^{m+n+1}(m+n-k)\left( \binom{k-1}{m-1}-\binom{k-1}{n-1} \right)G_{m+n+1-k}(\tau)I^A(k),
\end{align}
where we recall that by definition $G_n(\tau) \equiv 0$ whenever $n$ is odd. In particular, $\frac{\partial}{\partial \tau}I^A(m,n;\tau)=0$ if $m+n$ is even, and is given by
\begin{equation} \label{eqn:cor2c}
I^A(m,n;\tau)=\frac{(2\pi i)^{m+n}}{2} \frac{B_mB_n}{m!n!}.
\end{equation}

conjecture.raw:
\label{conj:weight}
$\eZ^A$ is graded for the weight, i.e. the natural morphism
\begin{align}
\bigoplus_{N \geq 0} \eZ^A_N &\rightarrow \calo(\H)\\
(I^A_N)_{N \geq 0} &\mapsto \sum_{N \geq 0} I^A_N,
\end{align}
with $I^A_N \in \eZ^A_N$, induced by the inclusions $\eZ^A_N \subset \calo(\H)$, is injective.

remark.raw:
In~\cite{E}, one also finds a notion of B-elliptic multiple zeta value, which we denote here by $I^B(n_1,\dots,n_r;\tau)$, defined as iterated integrals along the other homology cycle $\beta$ of an elliptic curve. Similar to A-elliptic multiple zeta values, B-elliptic multiple zeta values can be obtained as coefficients of Enriquez's B-associator~\cite{E2}. The modular transformation formula (cf.~\cite{E}, eq.~(26))
\begin{equation}
I^B(n_1,\dots,n_r;\tau)=\tau^{-(n_1+\dots+n_r)+r}I^A(n_1,\dots,n_r;-\tau^{-1})
\end{equation}
establishes a close connection between A-elliptic and B-elliptic multiple zeta values. A more detailed treatment of B-elliptic multiple zeta values will be given elsewhere.

