\bigskip

\noindent
2.1. {\bf Iterated integrals.}

Let $\omega_1,\dots,\omega_r$ be a collection of smooth one-forms on a complex manifold $M$, and let $\gamma: [0,1] \rightarrow M$ be a piecewise smooth path. Write $f_i(t)\dd t$ for the pull back of $\omega_i$ along $\gamma$.
We define
\begin{equation}
\int_{\gamma}\omega_1\dots\omega_r:=\int_{0<t_1<\dots<t_r<1}f_1(t_1)\dd t_1\dots f_r(t_r)\dd t_r.
\end{equation}

Iterated integrals satisfy some important algebraic relations, among them the shuffle product formula
\begin{equation} \label{eqn:shuf}
\int_{\gamma}\omega_1\dots\omega_r\int_{\gamma}\omega'_1\dots\omega'_s=\int_{\gamma}\omega_1\dots\omega_r \shuffle \omega'_1\dots\omega'_s,
\end{equation}
the composition of paths formula
\begin{equation} \label{eqn:comp}
\int_{\gamma_1\gamma_2} \omega_1\dots\omega_r=\sum_{k=0}^r\int_{\gamma_1}\omega_1\dots\omega_k \int_{\gamma_2}\omega_{k+1}\dots\omega_r,
\end{equation}
and the reversal of paths formula
\begin{equation} \label{eqn:revpath}
\int_{\gamma^{-1}}\omega_1\dots\omega_r=(-1)^r\int_{\gamma}\omega_r\dots\omega_1.
\end{equation}
For a more detailed account of iterated integrals, we refer to~\cite{Ch}. 



























\bigskip

\noindent
2.2. {\bf The Kronecker series.}

Fix $\tau$ in the upper half-plane $\H:=\{\xi \in \C \, \vert \, \Im(\xi)>0\}$. We consider a version of the odd Jacobi theta function $\theta_{\tau}$, defined for $\xi \in \C$ by
\begin{equation}
\theta_{\tau}(\xi):=\sum_{n \in \Z}(-1)^nq^{\frac{1}{2}(n+\frac{1}{2})^2}e^{(n+\frac{1}{2})2\pi i\xi}, \quad q=e^{2\pi i\tau}.
\end{equation}

The \textit{Kronecker series} $F_{\tau}: \C \times \C \rightarrow \C$~\cite{W,Z} is the meromorphic function defined by the formula
\begin{equation}
F_{\tau}(\xi,\alpha)=\frac{\theta_{\tau}'(0)\theta_{\tau}(\xi+\alpha)}{\theta_{\tau}(\xi)\theta_{\tau}(\alpha)}.
\end{equation}
\end{dfn}
The Kronecker series is quasi-periodic with respect to lattice translations in both variables
\begin{align}
F_{\tau}(\xi+1,\alpha)=F_{\tau}(\xi,\alpha), \quad F_{\tau}(\xi+\tau,w)=e^{-2\pi i\frac{\Im(\xi)}{\Im(\tau)}\alpha}F_{\tau}(\xi,\alpha), \\
F_{\tau}(\xi,\alpha+1)=F_{\tau}(\xi,\alpha), \quad F_{\tau}(\xi,\alpha+\tau)=e^{-2\pi i\frac{\Im(\alpha)}{\Im(\tau)}\xi}F_{\tau}(\xi,\alpha).
\end{align}
Viewed as a function of either variable, it has simple poles along the lattice $\Z+\Z\tau$. For more on the Kronecker series, see for example~\cite{W}, Part~II, and~\cite{Z}.
