\noindent
1.4. {\bf The main result}
The principal algebraic object studied in this paper is the $\Q$-algebra of A-elliptic multiple zeta values $\eZ^A$. The notions of weight and depth of multiple zeta values have analogues for elliptic multiple zeta values, namely the \textit{weight} and the \textit{length}. The latter defines an ascending filtration $\cL_{\bullet}\eZ^A_N$ on $\eZ^A_N$, where $\eZ^A_N$ denotes the $\Q$-vector space spanned by elliptic multiple zeta values of weight $N$. Denote by $\gr^{\cL}_{\bullet}$ the associated graded. Since there are only finitely many elliptic multiple zeta values of a fixed weight and length, $\gr^{\cL}_l\eZ^A_N$ is finite-dimensional for every $l$ and $N$. Let 
\begin{equation}
D_{N,l}:=\dim_{\Q}\gr^{\cL}_l\eZ^A_N.
\end{equation}
The computation of $D_{N,1}$ is relatively easy. We have
\begin{equation} \label{eqn:l1}
D_{N,1}=\begin{cases}
1, & \mbox{if $N>0$ is even}\\
0, & \mbox{else}.
\end{cases}
\end{equation}
More precisely, one can show (Corollary \ref{cor:diff}) that elliptic multiple zeta values of length one and weight $N$ are contained in $\Q \cdot (2\pi i)^N$ and vanish for odd $N$, and \eqref{eqn:l1} follows immediately from this. The computation of $D_{N,2}$, which is more elaborate, is the main result of this paper.
\begin{mthm}
We have
\begin{equation} \label{eqn:l2}
D_{N,2}=\begin{cases}
0, & \mbox{if $N$ is even}\\
\left\lfloor \frac{N}{3} \right\rfloor+1, & \mbox{if $N$ is odd}.
\end{cases}
\end{equation}
\end{mthm}
In the course of proving \eqref{eqn:l2}, we proceed as follows: Elliptic multiple zeta values satisfy two families of $\Q$-linear relations, namely the \textit{shuffle relations} and the \textit{Fay relations}~\cite{BMMS}. In order to count the number of linearly independent such relations, we introduce the \textit{Fay-shuffle space} $\FSh_2(N)$
\footnote{Independently, this space has already been studied by Brown in an unpublished preprint, in a slightly different context \cite{BrownAnatomy}.}
in length two, which is an elliptic analogue of the (depth two) double-shuffle space defined in~\cite{IKZ} in the context of multiple zeta values. By construction, the dimension of $\FSh_2(N)$ gives an upper bound for $D_{N,2}$, and using representation theory of the symmetric group $S_3$, we obtain for $\dim_{\Q}\FSh_2(N)$ precisely the numbers on the right hand side of \eqref{eqn:l2} (Theorem \ref{thm:Fayshuf}). In particular, the main theorem for even $N$ follows already from this.
In order to prove \eqref{eqn:l2} for odd $N$, we need a linear independence result for the elliptic double zeta values $I^A(r,N-r)$ for $r=0,\dots,k$, where $k=\lfloor \frac N3 \rfloor$ (Theorem \ref{thm:linind}). This uses Enriquez's differential equation for elliptic multiple zeta values and ends the proof of the main theorem. Moreover, since there are no non-trivial relations between elliptic double zeta values of different weights (Theorem \ref{thm:weight}), it also follows from the proof that every relation between elliptic double zeta values is a consequence of shuffle and Fay relations.

\end{prf}
Following~\cite{BL}, Definition~7, we will consider $\Omega_{\tau}(\xi,\alpha)$ as a generating series of differential one-forms on $E^{\times}_{\tau}$. Recall that $F_{\tau}(\xi,\alpha)$ has a simple pole at $\alpha=0$, and that therefore $\Omega_{\tau}(\xi,\alpha)$ has a formal expansion in $\alpha$.
\begin{dfn}
Define a family $\{\omega^{(k)}\}_{k \geq 0}$ of real analytic differential one-forms on $E^{\times}_{\tau}$ by the formula
\begin{equation}
\Omega_{\tau}(\xi,\alpha)=\sum_{k \geq 0}\omega^{(k)}\alpha^{k-1}.
\end{equation}
\end{dfn}
Note that we have
\begin{equation}
\omega^{(k)}=f^{(k)}(\xi)\dd\xi,
\end{equation}
where each $f^{(k)}$ is a real analytic function on $E^{\times}_{\tau}$. The $\omega^{(k)}$ satisfy properties analogous to $\Omega_{\tau}(\xi,\alpha)$.
\begin{cor} \label{cor:fk}
The form $\omega^{(k)}$ has modular weight $k+1$, i.e.
\begin{equation}
\omega^{(k)}_{\vert \gamma}=(c\tau+d)^{k+1}\omega^{(k)}
\end{equation}
where the action of $\gamma \in \SL_2(\Z)$ on $\omega^{(k)}$ is defined as in~\eqref{eqn:Omegamod}. Moreover, $\omega^{(k)}=f^{(k)}(\xi)\dd\xi$ is doubly periodic and antisymmetric/symmetric depending on the weight
\begin{equation}
f^{(k)}(-\xi)=(-1)^kf^{(k)}(\xi),
\end{equation}
and we have the Fay identity
\begin{align}
f^{(m)}(\xi_1)f^{(n)}(\xi_2)&=-(-1)^nf^{(m+n)}(\xi_1-\xi_2) \notag\\
&+\sum_{r=0}^{n}\binom{m+r-1}{m-1}f^{(n-r)}(\xi_2-\xi_1)f^{(m+r)}(\xi_1) \notag\\
&+\sum_{r=0}^{m}\binom{n+r-1}{n-1}f^{(m-r)}(\xi_1-\xi_2)f^{(n+r)}(\xi_2).
\end{align}
\qed

For example, if $w$ is the word $yx^{n_1}\dots yx^{n_r}$ and $\underline{n}=(n_1,\dots,n_r)$, then the coefficient $T^{\Reg}(\alpha)_w$ is obtained from expanding Lie monomials $\ad^k(x)(y)$ into linear combinations of words in $x,y$, and then collecting the respective terms in \eqref{eqn:kzbeqn}. The result is
\begin{equation} \label{eqn:transl}
T^{\Reg}(\alpha)_w=(-1)^{n_1+\dots+n_r}I^A(\underline{n};\tau)+\sum_{\underline{n'} \prec \underline{n}} c_{\underline{n'}}I^A(\underline{n'};\tau),
\end{equation}
for integers $c_{\underline{n'}} \in \Z$ coming from the expansion of Lie monomials $\ad^{k}(x)(y)$. Here and in the following, the multi-indices $\underline{n} \in \N^r$ being ordered lexicographically for the natural order on $\N$.
\begin{prop} \label{prop:transl}
For every collection of integers $n_1,\dots,n_r \geq 0$, the A-elliptic multiple zeta value $I^A(n_1,\dots,n_r;\tau)$ is a $\Z$-linear combination of coefficients of $T^{\Reg}(\alpha)_w$.
\end{prop}
In particular, this proves that every A-elliptic multiple zeta value is the restriction of a homotopy invariant iterated integral.

\begin{prf}
We use induction on the set of multi-indices of a fixed length $r$, ordered lexicographically. For $\underline{n}=(0,\dots,0) \in \N^r$, it is clear that
\begin{equation}
I^A(0,\dots,0;\tau)=T^{\Reg}(\alpha)_{y^r}.
\end{equation}
Now let $\underline{n}=(n_1,\dots,n_r)$ be a multi-index of length $r$ and assume the proposition for all multi-indices $\underline{n'}$ such that $\underline{n'} \prec \underline{n}$ in the lexicographical ordering. Now by \eqref{eqn:transl}, we have
\begin{equation}
I^A(\underline{n};\tau)=(-1)^{n_1+\dots+n_r}\left(T^{\Reg}(\alpha)_w-\sum_{\underline{n'} \prec \underline{n}} c_{\underline{n'}}I^A(\underline{n'};\tau) \right),
\end{equation}
where $w=yx^{n_1}\dots yx^{n_r}$. The terms on the right hand side of the last equation can be expressed as coefficients of $T^{\Reg}(\alpha)$, by the induction hypothesis, and this ends the proof.

